// getQR asks for a link's QR code with an optional session cookie.
func getQR(t *testing.T, srv *httptest.Server, slug, token string) (*http.Response, []byte) {
	t.Helper()
	req, err := http.NewRequestWithContext(context.Background(), http.MethodGet, srv.URL+"/api/links/"+slug+"/qr", nil)
	if err != nil {
		t.Fatal(err)
	}
	if token != "" {
		req.Header.Set("Cookie", server.SessionCookie+"="+token)
	}
	res, err := srv.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer func() { _ = res.Body.Close() }()
	body, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatal(err)
	}
	return res, body
}

// TestQRCode checks GET /api/links/<slug>/qr answers 200 image/png to the
// link's owner, 401 without a session and 404 for an unknown or another
// user's slug.
func TestQRCode(t *testing.T) {
	f := newQRFixture(t)
	srv := newServerWithStore(t, f.st)

	res, body := getQR(t, srv, f.slug, f.token)
	if res.StatusCode != http.StatusOK {
		t.Fatalf("GET /api/links/%s/qr with a session: %d %q, want 200", f.slug, res.StatusCode, body)
	}
	if got := res.Header.Get("Content-Type"); got != "image/png" {
		t.Fatalf("Content-Type %q, want image/png", got)
	}
	if len(body) == 0 {
		t.Fatal("the PNG body is empty")
	}

	res, body = getQR(t, srv, f.slug, "")
	if res.StatusCode != http.StatusUnauthorized {
		t.Fatalf("GET qr with no cookie: %d %q, want 401", res.StatusCode, body)
	}

	res, body = getQR(t, srv, "nosuchslug", f.token)
	if res.StatusCode != http.StatusNotFound {
		t.Fatalf("GET qr of an unknown slug: %d %q, want 404", res.StatusCode, body)
	}

	ctx := context.Background()
	other := &store.User{Email: "other@example.com", PasswordHash: "x"}
	if err := f.st.CreateUser(ctx, other); err != nil {
		t.Fatal(err)
	}
	otherToken := strings.Repeat("o", 43)
	if err := f.st.CreateSession(ctx, &store.Session{Token: otherToken, UserID: other.ID, ExpiresAt: time.Now().Add(time.Hour)}); err != nil {
		t.Fatal(err)
	}
	res, body = getQR(t, srv, f.slug, otherToken)
	if res.StatusCode != http.StatusNotFound {
		t.Fatalf("GET qr of another user's link: %d %q, want 404", res.StatusCode, body)
	}
}

// TestQRCodePNG checks the response body is a valid PNG holding a decodable
// QR of the request's own short URL.
func TestQRCodePNG(t *testing.T) {
	f := newQRFixture(t)
	srv := newServerWithStore(t, f.st)

	res, body := getQR(t, srv, f.slug, f.token)
	if res.StatusCode != http.StatusOK {
		t.Fatalf("GET qr: %d %q, want 200", res.StatusCode, body)
	}
	sig := []byte{0x89, 'P', 'N', 'G', 0x0d, 0x0a, 0x1a, 0x0a}
	if len(body) < len(sig) || !bytes.Equal(body[:len(sig)], sig) {
		t.Fatalf("body starts with % x, want the PNG signature % x", body[:min(len(body), 8)], sig)
	}
	img, err := png.Decode(bytes.NewReader(body))
	if err != nil {
		t.Fatalf("the PNG signature heads a body that is no PNG: %v", err)
	}
	if img.Bounds().Dx() < 256 || img.Bounds().Dy() < 256 {
		t.Fatalf("the PNG is %dx%d, want at least 256x256", img.Bounds().Dx(), img.Bounds().Dy())
	}
	want := srv.URL + "/" + f.slug
	if got := decodeQR(t, img); got != want {
		t.Fatalf("the QR holds %q, want %q", got, want)
	}
}

// decodeQR reads the payload back out of a QR image.
func decodeQR(t *testing.T, img image.Image) string {
	t.Helper()
	bmp, err := gozxing.NewBinaryBitmapFromImage(gray(img))
	if err != nil {
		t.Fatal(err)
	}
	result, err := gozxingqrcode.NewQRCodeReader().Decode(bmp, nil)
	if err != nil {
		t.Fatalf("no QR decodes out of the PNG: %v", err)
	}
	return result.GetText()
}

// gray copies an image into a Gray one, so that the decoder sees pixels
// whatever the PNG's colour model was.
func gray(src image.Image) image.Image {
	b := src.Bounds()
	out := image.NewGray(b)
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			out.SetGray(x, y, color.GrayModel.Convert(src.At(x, y)).(color.Gray))
		}
	}
	return out
}

